import copy, math, random
from merging import merge_settings

def reference(a,b):
 result=copy.deepcopy(a)
 for k,v in b.items():
  result[k]=reference(a[k],v) if k in a and isinstance(a[k],dict) and isinstance(v,dict) else copy.deepcopy(v)
 return result
rng=random.Random(3741)
def value(depth):
 if depth<=0:return rng.choice([None,True,False,0,1,-5,'', 'snow',1.5])
 kind=rng.randrange(3)
 if kind==0:return {str(i):value(depth-1) for i in range(rng.randrange(4))}
 if kind==1:return [value(depth-1) for _ in range(rng.randrange(4))]
 return value(0)
for i in range(100):
 a={str(j):value(3) for j in range(rng.randrange(5))};b={str(j):value(3) for j in range(rng.randrange(5))}
 before=copy.deepcopy((a,b));out=merge_settings(a,b)
 assert out==reference(a,b) and (a,b)==before
 a['sentinel']={'x':[1]};b['other']=[2]
 assert 'sentinel' not in out and 'other' not in out
base={'a':{'keep':[1,{'x':2}]},'b':[3]};over={'c':{'x':[4]},'a':{'new':[5]}}
out=merge_settings(base,over);out['a']['keep'][1]['x']=90;out['a']['new'].append(6);out['b'].append(7);out['c']['x'].append(8)
assert base=={'a':{'keep':[1,{'x':2}]},'b':[3]} and over=={'c':{'x':[4]},'a':{'new':[5]}}
assert merge_settings({'a':{'x':1}},{'a':None})=={'a':None}
for bad in [None,[],1,True,'x',{1:2},{'x':(1,)},{'x':float('nan')},{'x':[float('inf')]},{'x':{'a':set()}}]:
 for a,b in [(bad,{}),({},bad),(bad,{'x':0})]:
  try:merge_settings(a,b)
  except ValueError:pass
  else:raise AssertionError('accepted invalid input')
print('merge-ok')

